command:
size_of_type(){
  dir="$1"
  ext="$2"
  size=$(find "$dir" -type f -name "*.$ext" -exec du -sm {} + | awk '{s+=$1} END {print s}')
  printf "%.3f MB\n" "$size"
}

expected:
total_size() {
  local dir="$1"
  local ext="$2"
  local bytes=$(find "$dir" -type f -name "*.$ext" -printf "%s\n" | awk '{total+=$1} END {print total}')
  printf "Total size: %.3f MB\n" "$(echo "scale=6; $bytes/1024/1024" | bc)"
}

command:
git_rebase_test_push() {
  local branch="$1"
  local prev=$(git rev-parse --abbrev-ref HEAD)
  git checkout "$branch" && git rebase master && \
    if ./run_tests.sh; then git push origin "$branch"; else git rebase --abort; git checkout "$prev"; fi
}

expected:
git_rebase_and_push() {
  local branch=$1 prev=$(git rev-parse --abbrev-ref HEAD)
  git checkout "$branch" && git fetch origin && git rebase origin/main && make test && git push origin "$branch" || { git rebase --abort; git checkout "$prev"; }
}

command:
#!/usr/bin/env bash
sem(){
  while (( $(jobs -r | wc -l) >= 10 )); do sleep 0.1; done
  "$@" &
}
while read -r host; do
  sem bash -c "if ping -c1 -W2 \"$host\" &>/dev/null; then echo \"$host\" >> reachable.txt; else echo \"$host\" >> unreachable.txt; fi"
done < hosts.txt
wait

size_by_ext(){
  local dir="$1"
  find "$dir" -type f -exec stat -c "%s %f" {} + |\
    awk '{sum+=$1; ext[$2]+=$1} END{print "Total size:",sum; for(e in ext) printf "%s: %s bytes\n", e, ext[e]}' |\
    sort -k2 -nr
}

expected:
csvfile="data.csv"
awk -F, -v today=$(date +%s) 'NR>1 {
  cmd="date -d "$1" +%s"; cmd|getline ts; close(cmd);
  if (today - ts <= 30*24*3600) sum+=$2
} END {print sum}' "$csvfile"

tmpfifo=$(mktemp -u); mkfifo "$tmpfifo" && {
  while :; do date; sleep 1; done > "$tmpfifo" &
  head -n 5 < "$tmpfifo"
  kill $! 2>/dev/null
  rm -f "$tmpfifo"
}
